import json,hashlib
from scripts.training.v6_policy_resolution import DIRECTORY,OUTPUT,rows,write
from ai.training.contextual_support_policy import ContextualSupportTransport
from ai.training.support_task_review import TaskResponseReviewer
for stage in ['original','confirmation']:
 p=OUTPUT/('bounded-v11-'+stage);source=DIRECTORY/'bounded-support-v11'/stage
 recorditer=iter(rows(p/'all-provider-calls.jsonl'));pos=[0]
 class Replay:
  def complete(self,arm,messages,tools,decoding):
   r=next(recorditer);pos[0]+=1
   assert r['model']==arm['model'],(r['model'],arm['model'])
   assert hashlib.sha256(json.dumps(messages,sort_keys=True).encode()).hexdigest()==r['messages_sha256']
   return {k:r[k] for k in ['response','usage','finish_reason']}|{'tool_calls':[]}
 cfg=json.loads((source/'config.json').read_text());cases={r['id']:r for r in rows(source/'cases.jsonl')};arms={r['id']:r for r in cfg['arms']};judge=json.loads((DIRECTORY/'calibration-v2/gemma4-calibration-config.json').read_text())['arms'][0]
 raw=Replay();t=ContextualSupportTransport(raw,judge);t.task_reviewer=TaskResponseReviewer(raw,judge,json.loads((DIRECTORY/'task-review-v3/certificate.json').read_text()));t.task_fallback_arm=arms['base'];out=[]
 for row in rows(p/'results.jsonl'):
  try:
   result=t.complete(arms[row['arm_id']],cases[row['case_id']]['messages'],[],cfg['decoding']);err=None
  except Exception as e:err=f'{type(e).__name__}: {e}'
  if row['status']=='error' or err:out.append({'case_id':row['case_id'],'arm':row['arm_id'],'error':err})
 print(stage,out);write(source/'error-replay.json',out)
